/* Visão detalhada das regras de frete; dados e resultados explicitamente demonstrativos. */
function freightBadge(state) { return badge(F.labels[state],state==='deviation'?'amber':state==='pending'?'blue':state==='na'?'':'green'); }
function rate(n) { return Number.isFinite(n)?n.toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4}):'Não informada'; }
function freightDetail(op) {
  const r=M.financial(op), coverage=F.coverage(op), context=op.freight?.context;
  if(!r.requested) return outside('frete');
  const total=Object.entries(r.totals).map(([c,v])=>money(v,c)).join(' + ');
  return `<section class="conclusion ${r.status}"><div><div class="eyebrow">${op.entryContext?.paymentState==='Pago'?'AUDITORIA APÓS O PAGAMENTO':'CONFERÊNCIA ANTES DO PAGAMENTO'}</div><h2>${total ? `${total} para questionar` : 'Confira o alcance da conclusão'}</h2><p>${total?'Diferenças de cobrança na moeda original e impacto de câmbio em reais, apurados separadamente.':'As comparações disponíveis estão abaixo. Pendências de regra ou evidência impedem concluir a auditoria integral.'}</p><p class="small muted">${coverage.checked} de ${coverage.known} controles aplicáveis executados · ${coverage.pending} pendentes · ${coverage.na} não aplicáveis. Valor identificado não é valor recuperado.</p></div>${r.cases.length===1?button('Revisar contestação','communication',`data-invoice="${esc(r.cases[0].id)}"`,'primary'):''}</section>
    <nav class="freight-sections" aria-label="Seções da conferência">${[['charges','Cobranças'],['fx','Câmbio e PTAX'],['rules','Controles e exceções']].map(([id,label])=>button(label,'freight-jump',`data-section="freight-${id}"`,'small')).join('')}</nav>
    <details class="panel freight-context"><summary>Contexto, escopo e referência ${badge(coverage.pending?'Auditoria parcial':'Controles disponíveis concluídos',coverage.pending?'blue':'green')}</summary><div class="panel-body">${context?`<dl class="facts"><div><dt>Operação / modal</dt><dd>${esc(context.direction)} · ${esc(context.modal)}</dd></div><div><dt>Incoterm e local nomeado</dt><dd>${esc(context.incoterm)} · ${esc(context.place)}</dd></div><div><dt>Contratante / pagamento</dt><dd>${esc(context.contractor)} · ${esc(context.payment)}</dd></div><div><dt>Origem da referência</dt><dd>${esc(context.origin)}</dd></div><div><dt>Versão e aceite preservados</dt><dd>${esc(op.reference)} · ${date(context.accepted)} · ${esc(context.approver)}</dd></div><div><dt>Escopo financeiro</dt><dd>${esc(context.scope)}</dd></div></dl><p class="small muted">Contexto confirmado apenas no cenário DEMO. Incoterm, contratante e prepaid/collect são campos independentes.</p>`:op.entryContext?`<p>Contexto declarado na entrada: ${esc(op.entryContext.direction)} · ${esc(op.entryContext.modal)} · ${esc(op.entryContext.incoterm)} ${esc(op.entryContext.incotermVersion)} · ${esc(op.entryContext.namedPlace)}.</p><p>${esc(op.entryContext.contractor)} · ${esc(op.entryContext.payment)}. Fontes e regras ainda aguardam validação.</p>${button('Rever contexto e fontes','entry-resume',`data-id="${esc(op.id)}"`,'small')}`:'<p>Direção, Incoterm/versão/local nomeado, contratante, prepaid/collect e escopo ainda não confirmados nesta amostra. Não são deduzidos da rota.</p>'}</div></details>
    <section id="freight-charges" class="freight-section" tabindex="-1"><h2>Cobranças e bases de cálculo</h2><p class="small muted">Condição original, referência vigente autorizada e fatura — com detalhe de cada rubrica.</p>${op.invoices.map(i=>freightInvoice(op,i,r)).join('')}</section>
    <section id="freight-fx" class="freight-section" tabindex="-1"><h2>Câmbio e PTAX</h2><p class="small muted">Conferência da regra negociada com o agente, vinculada à data correta e à moeda da cobrança.</p>${op.invoices.map(i=>freightExchange(op,i)).join('')}</section>
    <section id="freight-rules" class="freight-section" tabindex="-1"><div class="panel-head"><div><h2>Controles e exceções</h2><p>${coverage.percent??'—'}% de cobertura · ${coverage.checked}/${coverage.known} aplicáveis. Itens não aplicáveis ficam fora do denominador.</p></div></div><div class="panel rule-matrix">${[...new Set(coverage.items.map(c=>c.group))].map(group=>`<div class="rule-group"><h3>${esc(group)}</h3>${coverage.items.filter(c=>c.group===group).map(c=>`<button class="rule-row" data-action="freight-control" data-control="${c.id}"><span><strong>${esc(c.name)}</strong><small>${esc(c.finding)}</small></span>${freightBadge(c.status)}<span aria-hidden="true">→</span></button>`).join('')}</div>`).join('')}</div></section>
    <section class="panel gap"><div class="panel-head"><h2>Da diferença à recuperação</h2></div><div class="financial-stages"><div><small>Identificado para questionar</small><strong>${total||'Ainda inconclusivo'}</strong></div><div><small>Contestado / enviado</small><strong>Não confirmado</strong></div><div><small>Reconhecido / credit note</small><strong>Não confirmado</strong></div><div><small>Recuperado / compensado</small><strong>Não confirmado</strong></div></div><div class="section-tail">A exportação do rascunho fica no log. Resposta, fatura corrigida, crédito e pagamento exigem evidências próprias.</div></section>`;
}
function freightInvoice(op,i,r) {
  const available=i.available&&i.reference;
  const caseReady=r.cases.includes(i);
  return `<section class="panel invoice-panel gap"><div class="panel-head"><div><h3>${esc(i.id)} · ${esc(i.currency)}</h3><p>${esc(i.issuer||op.agent)} · ${available?'Condição aceita × fatura':'Fonte pendente'}</p></div>${caseReady&&r.cases.length>1?button('Revisar contestação','communication',`data-invoice="${esc(i.id)}"`,'small'):badge(available?'Comparação disponível':'Falta fonte',available?'':'blue')}</div>${available?`<div class="table-wrap"><table class="compare-table freight-table"><thead><tr><th>Rubrica / local</th><th>Base e tarifa</th><th>Original / vigente</th><th>Faturado</th><th>Diferença</th><th>Resultado</th></tr></thead><tbody>${i.lines.map((l,index)=>{const q=F.charge(l);return `<tr class="${q.status==='deviation'?'flagged':''}"><td><strong>${esc(l.name)}</strong><small>${esc(l.group||'Local não informado')}${l.originalName&&l.originalName!==l.name?' · na fatura: '+esc(l.originalName):''}</small><button class="evidence-button" data-action="freight-line" data-invoice="${esc(i.id)}" data-index="${index}">Regra, cálculo e evidências</button></td><td data-label="Base e tarifa">${l.unit?`${l.quantity} × ${money(l.unitPrice,i.currency)}<small>por ${esc(l.unit)} · faturado: ${l.actualQuantity} × ${money(l.billedUnitPrice,i.currency)}</small>`:'Unidade e quantidade pendentes'}</td><td data-label="Original / vigente">${money(l.agreed,i.currency)}${q.expected!==l.agreed?`<small>Vigente: ${money(q.expected,i.currency)}</small>`:''}</td><td data-label="Faturado">${money(l.billed,i.currency)}</td><td data-label="Diferença">${money(q.delta,i.currency)}<small>${q.percent===null?'Base zero/ausente · percentual não aplicável':q.percent.toLocaleString('pt-BR')+'%'}</small></td><td>${freightBadge(q.status)}<small>${l.tolerance==null?'Tolerância não definida':'Tolerância: '+money(l.tolerance,i.currency)+' por rubrica · DEMO'}</small></td></tr>`;}).join('')}</tbody></table></div><div class="section-tail">Diferença contra referência vigente; cotação original preservada. Valores a menor não compensam aumentos de outras rubricas. Taxa cambial detalhada abaixo.</div>`:`<div class="panel-body"><p>${!i.available?'Fatura ainda não recebida.':'Referência com aceite não vinculada.'} Comparações dependentes ficam pendentes.</p>${button('Completar fonte','missing',`data-invoice="${esc(i.id)}"`,'small')}</div>`}</section>`;
}
function freightExchange(op,i) {
  const fx=op.freight?.fx?.[i.id], q=F.exchange(op,i);
  return `<section class="panel gap"><div class="panel-head"><div><h3>${esc(i.id)} · ${fx?esc(fx.from||i.currency)+' → '+esc(fx.to||i.currency):'Conversão a confirmar'}</h3><p>${fx?esc(fx.ruleEvidence||fx.reason):'Regra, data e moeda de liquidação não confirmadas'}</p></div>${freightBadge(q.status)}</div><div class="panel-body">${q.status==='na'?`<p>${esc(q.reason)}</p>`:fx?`<dl class="fx-grid"><div><dt>Evento contratual</dt><dd>${esc(fx.event)} · ${date(fx.eventDate)}</dd></div><div><dt>Regra da data</dt><dd>${esc(fx.dateRule)}</dd><small>${esc(fx.calendar)}</small></div><div><dt>Referência × data aplicada</dt><dd>${date(fx.referenceDate)} × ${date(fx.appliedDate)}</dd></div><div><dt>Boletim / lado</dt><dd>${esc(fx.bulletin)} · ${esc(fx.side)}</dd></div><div><dt>PTAX de referência · DEMO</dt><dd>${rate(fx.referenceRate)} BRL/USD</dd></div><div><dt>Spread aprovado</dt><dd>${fx.spread} ${fx.spreadType==='percent'?'%':'BRL/USD'} · ${fx.spreadType==='percent'?'percentual':'acréscimo absoluto'}</dd></div><div><dt>Taxa esperada</dt><dd>${rate(q.expectedRate)} BRL/USD</dd></div><div><dt>Taxa da fatura</dt><dd>${rate(fx.appliedRate)} BRL/USD</dd></div></dl>${Number.isFinite(q.delta)?`<div class="fx-calculation"><div><small>Mesma base faturada</small><strong>${money(q.base,i.currency)}</strong></div><span>×</span><div><small>Diferença entre taxas</small><strong>${rate(fx.appliedRate)} − ${rate(q.expectedRate)}</strong></div><span>=</span><div><small>Impacto cambial</small><strong>${money(q.delta,'BRL')}</strong></div></div><p class="small">Com a taxa esperada: ${money(q.expected,'BRL')} · com a taxa aplicada: ${money(q.billed,'BRL')}. Desvio de taxa: ${q.percent}%. Tolerância do exemplo: ${money(fx.tolerance,'BRL')} por conversão.</p>`:''}<p class="small muted">Taxa esperada = PTAX ${fx.spreadType==='percent'?'× (1 + spread/100)':' + spread'}. Arredondamento DEMO: taxa a 4 casas; totais a 2 casas. O impacto cambial usa a mesma base faturada, isolado das diferenças de rubrica em USD.</p><p class="small muted">Taxas 5,0000 / 5,1000 / 5,2000 são fictícias para revisão. Não houve consulta do boletim real desta data.</p>`:`<p>${esc(q.reason)}</p><p class="small muted">Sem convenção aprovada, a comparação permanece inconclusiva. Não assumir PTAX do dia, fechamento, venda ou spread zero.</p>`}${q.reason&&fx?`<p class="status-warning">${esc(q.reason)}</p>`:''}<div class="source-actions gap">${button('Ver regra e evidências','freight-control','data-control="fx"','small')}<a class="btn small" href="https://ptax.bcb.gov.br/ptax_internet/consultaBoletim.do?method=consultarBoletim" target="_blank" rel="noopener">Consultar boletins no BCB ↗</a></div></div></section>`;
}
function freightEvidenceText(op,key) {
  const [,invoiceId,index]=key.split(':');
  if(key==='freight-context') return `CONTEXTO DEMONSTRATIVO\n${JSON.stringify(op.freight?.context||{status:'Contexto ainda não confirmado'},null,2)}\nCobertura: ${F.coverage(op).checked}/${F.coverage(op).known} controles; conclusão limitada às fontes disponíveis.`;
  const i=op.invoices.find(i=>i.id===invoiceId);
  if(!i) return 'Fatura não localizada.';
  if(key.startsWith('fx:')) {
    const fx=op.freight?.fx?.[i.id], q=F.exchange(op,i);
    return `CÂMBIO E PTAX — REPRESENTAÇÃO DEMO\n${i.id}\n${fx?`Regra: ${fx.ruleEvidence}\nEvento: ${fx.event} ${fx.eventDate}\nConvenção: ${fx.dateRule}\nReferência: ${fx.referenceDate}; aplicação: ${fx.appliedDate}\nBoletim: ${fx.bulletin}; lado: ${fx.side}\nFonte: ${fx.referenceEvidence}\nTaxa fictícia: ${rate(fx.referenceRate)}; spread: ${fx.spread} (${fx.spreadType})\nEsperada: ${rate(q.expectedRate)}; faturada: ${rate(fx.appliedRate)}\nBase: ${money(q.base,i.currency)}\nEsperado: ${money(q.expected,'BRL')}; faturado: ${money(q.billed,'BRL')}; impacto: ${money(q.delta,'BRL')}\nTolerância DEMO: ${money(fx.tolerance,'BRL')}; arredondamento: taxa 4 casas, totais 2.`:q.reason}\nResultado: ${F.labels[q.status]}\n${q.reason||''}\nBCB não consultado para esta taxa; exemplo não serve para pagamento real.`;
  }
  const l=i.lines[Number(index)], q=F.charge(l);
  return `RUBRICA DEMONSTRATIVA\n${i.id} · ${l.name}\nOriginal: ${money(l.agreed,i.currency)}; vigente: ${money(q.expected,i.currency)}\nFaturado: ${money(l.billed,i.currency)}; diferença: ${money(q.delta,i.currency)}; percentual: ${q.percent??'não aplicável'}\nBase: ${l.quantity??'pendente'} ${l.unit||'unidade pendente'} × ${money(l.unitPrice,i.currency)}; fatura: ${l.actualQuantity??'pendente'} × ${money(l.billedUnitPrice,i.currency)}\nNomenclatura: ${l.originalName||l.name}; equivalência: ${l.normalizationEvidence||'pendente'}\nTolerância: ${l.tolerance==null?'não definida':money(l.tolerance,i.currency)+' · DEMO'}\nAlteração: ${l.change?JSON.stringify(l.change):'nenhuma aprovação adicional vinculada'}\n${l.note||''}\nResultado: ${F.labels[q.status]}. Causa e responsabilidade não comprovadas só pela diferença.`;
}
function openFreightControl(op,id) {
  const c=F.controls(op).find(c=>c.id===id);
  const extra=id==='fx'?op.invoices.map(i=>`<pre class="source-pre">${esc(freightEvidenceText(op,'fx:'+i.id))}</pre>`).join(''):'';
  openDrawer(c.name,`${freightBadge(c.status)}<p class="gap">${esc(c.finding)}</p><dl class="facts"><div><dt>Regra</dt><dd>${esc(c.rule)}</dd></div><div><dt>Fontes</dt><dd>${esc(c.evidence)}</dd></div><div><dt>Ação recomendada</dt><dd>${esc(c.action)}</dd></div><div><dt>Responsável / prazo</dt><dd>${esc(c.owner)} · ${esc(c.deadline)}</dd></div></dl>${extra}<p class="small muted gap">Comparação DEMO. Causa/responsabilidade não são inferidas; parâmetros e evidências produtivos ainda precisam ser vinculados.</p><a class="btn small" href="${auditTabUrl(op,'documentos')}">Documentos e vínculos</a>`,button('Voltar à conferência','close'));
}
function freightDocuments(op) {
  return `<section class="panel gap"><div class="panel-head"><h2>Exigibilidade e cobertura do frete</h2></div><div class="panel-body">${op.freight?.records?.length?op.freight.records.map(d=>`<div class="document-link-row"><div><div><strong>${esc(d.name)}</strong><small>${esc(d.type)} · ${esc(d.requirement)}</small><small>${esc(d.source)} · afeta: ${esc(d.impact)}</small></div></div>${badge(d.availability,d.availability==='Pendente'?'blue':d.availability==='Não aplicável'?'':'green')}</div>`).join(''):'<p>Matriz de exigibilidade ainda não confirmada para esta operação. Ausência documental não é divergência.</p>'}<p class="small muted gap">Evidência substituta ou dispensa exige justificativa, usuário, data e aprovador; a prévia não concede dispensas automaticamente.</p></div></section>`;
}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');
  if(!b) return;
  if(b.dataset.action==='freight-jump') {const section=document.getElementById(b.dataset.section);section?.scrollIntoView({block:'start'});section?.focus({preventScroll:true});}
  if(b.dataset.action==='freight-control') openFreightControl(operation(),b.dataset.control);
  if(b.dataset.action==='freight-line') openDrawer('Regra, cálculo e evidências',`<pre class="source-pre">${esc(freightEvidenceText(operation(),`freight-line:${b.dataset.invoice}:${b.dataset.index}`))}</pre>`,button('Voltar à conferência','close'));
});
